arguments.file_text:
:root {
  --bg: #0a0a0c;
  --bg-elev: #131318;
  --bg-elev-2: #1c1c24;
  --border: #26262f;
  --border-strong: #36363f;
  --text: #f4f4f6;
  --text-muted: #a0a0ae;
  --text-dim: #6e6e7c;
  --accent: #c8ff3e;
  --accent-ink: #0a0a0c;
  --danger: #ff5470;
  --warn: #ffb547;
  --radius: 14px;
  --radius-sm: 8px;
  --shadow: 0 10px 30px rgba(0, 0, 0, 0.45);
  --maxw: 1280px;
  --focus: 0 0 0 2px var(--bg), 0 0 0 4px var(--accent);
}

* { box-sizing: border-box; }

html { color-scheme: dark; }

body {
  margin: 0;
  background: radial-gradient(1200px 600px at 80% -10%, rgba(200, 255, 62, 0.08), transparent 60%),
              radial-gradient(900px 500px at -10% 10%, rgba(120, 90, 255, 0.08), transparent 60%),
              var(--bg);
  color: var(--text);
  font-family: "Inter", system-ui, -apple-system, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  font-size: 16px;
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
  min-height: 100vh;
}

img { max-width: 100%; display: block; }

a {
  color: inherit;
  text-decoration: none;
}

a:hover { text-decoration: underline; }

button {
  font: inherit;
  color: inherit;
  background: none;
  border: 0;
  cursor: pointer;
}

:focus-visible {
  outline: none;
  box-shadow: var(--focus);
  border-radius: var(--radius-sm);
}

.skip-link {
  position: absolute;
  left: 0;
  top: 0;
  background: var(--accent);
  color: var(--accent-ink);
  padding: 12px 16px;
  font-weight: 600;
  transform: translateY(-150%);
  z-index: 1000;
}
.skip-link:focus { transform: translateY(0); }

.container {
  max-width: var(--maxw);
  margin: 0 auto;
  padding: 0 24px;
}

/* ---------- Top promo bar ---------- */
.promo-bar {
  background: var(--bg-elev-2);
  color: var(--text-muted);
  border-bottom: 1px solid var(--border);
  font-size: 13px;
}
.promo-bar__inner {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 16px;
  padding: 8px 24px;
  max-width: var(--maxw);
  margin: 0 auto;
}
.promo-bar strong { color: var(--text); }
.promo-bar__links { display: flex; gap: 18px; }
.promo-bar__links a:hover { color: var(--text); }

/* ---------- Header ---------- */
.site-header {
  position: sticky;
  top: 0;
  z-index: 50;
  background: rgba(10, 10, 12, 0.85);
  backdrop-filter: saturate(160%) blur(12px);
  -webkit-backdrop-filter: saturate(160%) blur(12px);
  border-bottom: 1px solid var(--border);
}
.site-header__inner {
  display: grid;
  grid-template-columns: auto 1fr auto;
  align-items: center;
  gap: 24px;
  padding: 16px 24px;
  max-width: var(--maxw);
  margin: 0 auto;
}
.brand {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  font-weight: 800;
  letter-spacing: 0.02em;
  font-size: 18px;
}
.brand__mark {
  width: 28px; height: 28px;
  border-radius: 8px;
  background: linear-gradient(135deg, var(--accent), #6cf);
  display: inline-grid;
  place-items: center;
  color: var(--accent-ink);
  font-weight: 900;
}

.primary-nav ul {
  display: flex;
  gap: 8px;
  margin: 0;
  padding: 0;
  list-style: none;
  justify-content: center;
}
.primary-nav a {
  display: inline-block;
  padding: 8px 12px;
  border-radius: 999px;
  color: var(--text-muted);
  font-weight: 500;
}
.primary-nav a:hover { color: var(--text); background: var(--bg-elev); text-decoration: none; }
.primary-nav a[aria-current="page"] {
  color: var(--text);
  background: var(--bg-elev);
}

.header-actions {
  display: flex;
  align-items: center;
  gap: 6px;
}
.icon-btn {
  position: relative;
  width: 40px; height: 40px;
  display: inline-grid;
  place-items: center;
  border-radius: 10px;
  color: var(--text-muted);
}
.icon-btn:hover { color: var(--text); background: var(--bg-elev); }
.icon-btn .badge {
  position: absolute;
  top: 4px; right: 4px;
  min-width: 18px; height: 18px;
  padding: 0 5px;
  border-radius: 999px;
  background: var(--accent);
  color: var(--accent-ink);
  font-size: 11px;
  font-weight: 700;
  display: inline-grid;
  place-items: center;
  border: 2px solid var(--bg);
}

.search {
  position: relative;
  flex: 1;
  max-width: 360px;
}
.search input {
  width: 100%;
  background: var(--bg-elev);
  border: 1px solid var(--border);
  color: var(--text);
  padding: 10px 12px 10px 38px;
  border-radius: 10px;
  font: inherit;
}
.search input::placeholder { color: var(--text-dim); }
.search svg {
  position: absolute;
  left: 12px; top: 50%;
  transform: translateY(-50%);
  color: var(--text-dim);
  pointer-events: none;
}

/* ---------- Hero ---------- */
.hero {
  position: relative;
  margin-top: 32px;
  border: 1px solid var(--border);
  border-radius: 24px;
  overflow: hidden;
  background:
    radial-gradient(700px 400px at 85% 30%, rgba(200, 255, 62, 0.18), transparent 60%),
    linear-gradient(135deg, #16161d 0%, #0d0d12 100%);
}
.hero__grid {
  display: grid;
  grid-template-columns: 1.1fr 0.9fr;
  gap: 40px;
  padding: 64px;
  align-items: center;
}
.hero__eyebrow {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 6px 12px;
  border: 1px solid var(--border-strong);
  border-radius: 999px;
  font-size: 12px;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: var(--text-muted);
  margin-bottom: 20px;
}
.hero__eyebrow .dot {
  width: 6px; height: 6px;
  border-radius: 50%;
  background: var(--accent);
  box-shadow: 0 0 0 4px rgba(200, 255, 62, 0.15);
}
.hero h1 {
  font-size: clamp(2.4rem, 5vw, 4rem);
  line-height: 1.05;
  margin: 0 0 16px;
  letter-spacing: -0.02em;
  font-weight: 800;
}
.hero h1 em {
  font-style: normal;
  background: linear-gradient(120deg, var(--accent), #88f);
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
}
.hero p.lede {
  color: var(--text-muted);
  font-size: 1.05rem;
  max-width: 52ch;
  margin: 0 0 28px;
}
.hero__cta {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
  align-items: center;
}
.btn {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 12px 20px;
  border-radius: 10px;
  font-weight: 600;
  border: 1px solid transparent;
  transition: transform 0.05s ease, background 0.2s ease, border-color 0.2s ease;
}
.btn:hover { text-decoration: none; }
.btn:active { transform: translateY(1px); }
.btn--primary {
  background: var(--accent);
  color: var(--accent-ink);
}
.btn--primary:hover { background: #d6ff63; }
.btn--ghost {
  border-color: var(--border-strong);
  color: var(--text);
}
.btn--ghost:hover { background: var(--bg-elev); }
.btn--block { width: 100%; justify-content: center; }

.hero__meta {
  margin-top: 36px;
  display: flex;
  gap: 32px;
  color: var(--text-muted);
  font-size: 14px;
}
.hero__meta strong { color: var(--text); display: block; font-size: 1.4rem; font-weight: 700; }

.hero__visual {
  position: relative;
  aspect-ratio: 4 / 5;
  border-radius: 18px;
  overflow: hidden;
  background: linear-gradient(160deg, #2a2a36, #14141a);
  border: 1px solid var(--border-strong);
}
.hero__visual img {
  width: 100%; height: 100%;
  object-fit: cover;
}
.hero__tag {
  position: absolute;
  bottom: 16px; left: 16px;
  background: rgba(10, 10, 12, 0.7);
  backdrop-filter: blur(8px);
  border: 1px solid var(--border-strong);
  padding: 10px 14px;
  border-radius: 12px;
  font-size: 13px;
  display: flex; align-items: center; gap: 10px;
}
.hero__tag .price {
  color: var(--accent);
  font-weight: 700;
}

/* ---------- Sections ---------- */
section { margin-top: 80px; }
.section-head {
  display: flex;
  align-items: end;
  justify-content: space-between;
  gap: 16px;
  margin-bottom: 28px;
}
.section-head h2 {
  font-size: clamp(1.6rem, 2.6vw, 2.1rem);
  margin: 0;
  letter-spacing: -0.01em;
  font-weight: 700;
}
.section-head p { color: var(--text-muted); margin: 6px 0 0; }
.section-head a.see-all {
  color: var(--text-muted);
  font-weight: 500;
  white-space: nowrap;
}
.section-head a.see-all:hover { color: var(--accent); }

/* ---------- Category strip ---------- */
.categories {
  display: grid;
  grid-template-columns: repeat(6, 1fr);
  gap: 14px;
}
.category {
  background: var(--bg-elev);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 22px 16px;
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 10px;
  transition: border-color 0.2s ease, transform 0.2s ease, background 0.2s ease;
  color: var(--text);
}
.category:hover {
  border-color: var(--accent);
  background: var(--bg-elev-2);
  text-decoration: none;
  transform: translateY(-2px);
}
.category__icon {
  width: 36px; height: 36px;
  border-radius: 10px;
  background: var(--bg-elev-2);
  display: grid; place-items: center;
  color: var(--accent);
}
.category__name { font-weight: 600; }
.category__count { color: var(--text-dim); font-size: 13px; }

/* ---------- Product grid ---------- */
.product-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 20px;
}
.product {
  background: var(--bg-elev);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  overflow: hidden;
  display: flex;
  flex-direction: column;
  transition: border-color 0.2s ease, transform 0.2s ease;
}
.product:hover {
  border-color: var(--border-strong);
  transform: translateY(-3px);
}
.product__media {
  position: relative;
  aspect-ratio: 4 / 5;
  background: linear-gradient(160deg, #20202a, #101015);
  overflow: hidden;
}
.product__media img {
  width: 100%; height: 100%;
  object-fit: cover;
  transition: transform 0.4s ease;
}
.product:hover .product__media img { transform: scale(1.04); }
.product__badge {
  position: absolute;
  top: 12px; left: 12px;
  background: var(--bg);
  color: var(--text);
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.08em;
  padding: 4px 8px;
  border-radius: 6px;
  border: 1px solid var(--border-strong);
  text-transform: uppercase;
}
.product__badge--accent { background: var(--accent); color: var(--accent-ink); border-color: transparent; }
.product__badge--danger { background: var(--danger); color: #fff; border-color: transparent; }
.product__wishlist {
  position: absolute;
  top: 10px; right: 10px;
  width: 36px; height: 36px;
  border-radius: 50%;
  background: rgba(10, 10, 12, 0.6);
  backdrop-filter: blur(6px);
  display: grid; place-items: center;
  color: var(--text-muted);
  border: 1px solid var(--border);
}
.product__wishlist:hover, .product__wishlist[aria-pressed="true"] {
  color: var(--danger);
  background: rgba(255, 84, 112, 0.1);
  border-color: rgba(255, 84, 112, 0.4);
}
.product__body {
  padding: 16px;
  display: flex;
  flex-direction: column;
  gap: 8px;
  flex: 1;
}
.product__category {
  font-size: 12px;
  text-transform: uppercase;
  letter-spacing: 0.12em;
  color: var(--text-dim);
}
.product__title {
  font-size: 15px;
  font-weight: 600;
  margin: 0;
}
.product__title a:hover { color: var(--accent); text-decoration: none; }
.product__rating {
  display: flex;
  align-items: center;
  gap: 6px;
  color: var(--text-muted);
  font-size: 13px;
}
.product__rating .stars { color: var(--warn); letter-spacing: 1px; }
.product__price-row {
  margin-top: auto;
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 8px;
  padding-top: 8px;
}
.product__price {
  font-size: 1.05rem;
  font-weight: 700;
}
.product__price del {
  color: var(--text-dim);
  font-weight: 400;
  margin-left: 6px;
  font-size: 0.85em;
}
.product__add {
  background: var(--bg-elev-2);
  color: var(--text);
  border: 1px solid var(--border);
  padding: 8px 12px;
  border-radius: 8px;
  font-size: 13px;
  font-weight: 600;
  display: inline-flex;
  align-items: center;
  gap: 6px;
}
.product__add:hover { background: var(--accent); color: var(--accent-ink); border-color: transparent; }

/* ---------- Deals ---------- */
.deals {
  display: grid;
  grid-template-columns: 1.1fr 0.9fr;
  gap: 20px;
}
.deal-card {
  position: relative;
  border-radius: var(--radius);
  border: 1px solid var(--border);
  padding: 32px;
  overflow: hidden;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  min-height: 280px;
}
.deal-card--feature {
  background:
    radial-gradient(500px 250px at 100% 100%, rgba(200, 255, 62, 0.18), transparent 60%),
    linear-gradient(135deg, #1c1c25 0%, #0e0e13 100%);
}
.deal-card--split {
  display: grid;
  grid-template-rows: 1fr 1fr;
  padding: 0;
  background: transparent;
  border: 0;
  gap: 20px;
}
.deal-card--secondary {
  background: linear-gradient(135deg, rgba(120, 90, 255, 0.18), #15151c 70%);
  padding: 24px;
  min-height: 0;
  border-radius: var(--radius);
  border: 1px solid var(--border);
}
.deal-card--tertiary {
  background: linear-gradient(135deg, rgba(255, 84, 112, 0.18), #15151c 70%);
  padding: 24px;
  min-height: 0;
  border-radius: var(--radius);
  border: 1px solid var(--border);
}
.deal-card .eyebrow {
  text-transform: uppercase;
  letter-spacing: 0.2em;
  font-size: 11px;
  color: var(--accent);
  font-weight: 700;
}
.deal-card h3 {
  font-size: clamp(1.4rem, 2.4vw, 2rem);
  margin: 12px 0 8px;
  letter-spacing: -0.01em;
}
.deal-card p { color: var(--text-muted); margin: 0; max-width: 42ch; }
.deal-card__cta {
  margin-top: 22px;
  display: inline-flex;
  align-items: center;
  gap: 8px;
  font-weight: 600;
  color: var(--text);
}
.deal-card__cta:hover { color: var(--accent); text-decoration: none; }
.deal-card__cta:hover span.arrow { transform: translateX(3px); }
.deal-card__cta .arrow { transition: transform 0.2s ease; display: inline-block; }

.countdown {
  display: flex;
  gap: 8px;
  margin-top: 22px;
}
.countdown__cell {
  background: rgba(10, 10, 12, 0.5);
  border: 1px solid var(--border-strong);
  border-radius: 10px;
  padding: 10px 14px;
  text-align: center;
  min-width: 64px;
}
.countdown__num {
  display: block;
  font-size: 1.3rem;
  font-weight: 700;
  color: var(--text);
  font-variant-numeric: tabular-nums;
}
.countdown__lbl {
  display: block;
  font-size: 11px;
  text-transform: uppercase;
  letter-spacing: 0.12em;
  color: var(--text-dim);
  margin-top: 4px;
}

/* ---------- Editorial ---------- */
.editorial {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 20px;
}
.article {
  background: var(--bg-elev);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  overflow: hidden;
  display: flex;
  flex-direction: column;
  transition: border-color 0.2s ease, transform 0.2s ease;
}
.article:hover { border-color: var(--border-strong); transform: translateY(-3px); }
.article__media {
  aspect-ratio: 16 / 10;
  background: linear-gradient(160deg, #1f1f29, #101015);
  overflow: hidden;
}
.article__media img { width: 100%; height: 100%; object-fit: cover; }
.article__body { padding: 22px; display: flex; flex-direction: column; gap: 10px; }
.article__meta {
  display: flex;
  align-items: center;
  gap: 10px;
  font-size: 12px;
  color: var(--text-dim);
  text-transform: uppercase;
  letter-spacing: 0.1em;
}
.article__meta .tag {
  color: var(--accent);
  font-weight: 700;
}
.article__title {
  font-size: 1.15rem;
  line-height: 1.3;
  margin: 0;
  font-weight: 600;
}
.article__title a:hover { color: var(--accent); text-decoration: none; }
.article__excerpt { color: var(--text-muted); font-size: 14px; margin: 0; }
.article__read {
  margin-top: 6px;
  align-self: flex-start;
  color: var(--text);
  font-weight: 600;
  font-size: 14px;
}
.article__read:hover { color: var(--accent); text-decoration: none; }

/* ---------- Newsletter ---------- */
.newsletter {
  margin-top: 80px;
  border: 1px solid var(--border);
  border-radius: 24px;
  padding: 48px;
  background:
    radial-gradient(500px 250px at 0% 50%, rgba(200, 255, 62, 0.1), transparent 60%),
    linear-gradient(135deg, #16161d, #0d0d12);
  display: grid;
  grid-template-columns: 1.2fr 1fr;
  gap: 40px;
  align-items: center;
}
.newsletter h2 {
  font-size: clamp(1.6rem, 2.6vw, 2rem);
  margin: 0 0 8px;
  letter-spacing: -0.01em;
}
.newsletter p { color: var(--text-muted); margin: 0; max-width: 48ch; }
.newsletter__form {
  display: flex;
  gap: 8px;
  flex-direction: column;
}
.newsletter__row { display: flex; gap: 8px; }
.newsletter input[type="email"] {
  flex: 1;
  background: var(--bg);
  border: 1px solid var(--border-strong);
  color: var(--text);
  padding: 14px 16px;
  border-radius: 10px;
  font: inherit;
}
.newsletter input[type="email"]::placeholder { color: var(--text-dim); }
.newsletter__hint { font-size: 12px; color: var(--text-dim); }
.newsletter__status {
  font-size: 14px;
  color: var(--accent);
  min-height: 1.2em;
  font-weight: 600;
}

/* ---------- Footer ---------- */
.site-footer {
  margin-top: 80px;
  border-top: 1px solid var(--border);
  background: #08080b;
}
.site-footer__inner {
  display: grid;
  grid-template-columns: 1.2fr repeat(3, 1fr);
  gap: 40px;
  padding: 60px 24px 30px;
  max-width: var(--maxw);
  margin: 0 auto;
}
.site-footer h4 {
  font-size: 13px;
  text-transform: uppercase;
  letter-spacing: 0.12em;
  color: var(--text-muted);
  margin: 0 0 16px;
}
.site-footer ul { list-style: none; padding: 0; margin: 0; display: grid; gap: 10px; }
.site-footer a { color: var(--text-muted); }
.site-footer a:hover { color: var(--text); }
.site-footer__brand p { color: var(--text-muted); max-width: 36ch; margin: 12px 0 20px; }
.socials { display: flex; gap: 8px; }
.socials a {
  width: 36px; height: 36px;
  border-radius: 10px;
  border: 1px solid var(--border);
  display: grid; place-items: center;
  color: var(--text-muted);
}
.socials a:hover { color: var(--accent); border-color: var(--accent); }
.copyright {
  border-top: 1px solid var(--border);
  padding: 20px 24px;
  text-align: center;
  font-size: 13px;
  color: var(--text-dim);
  max-width: var(--maxw);
  margin: 0 auto;
}

/* ---------- Toast ---------- */
.toast-region {
  position: fixed;
  right: 24px;
  bottom: 24px;
  z-index: 200;
  display: grid;
  gap: 10px;
}
.toast {
  background: var(--bg-elev-2);
  border: 1px solid var(--border-strong);
  color: var(--text);
  padding: 12px 16px;
  border-radius: 10px;
  box-shadow: var(--shadow);
