  .hero__visual { aspect-ratio: 16 / 10; }
  .product-grid { grid-template-columns: repeat(3, 1fr); }
  .categories { grid-template-columns: repeat(3, 1fr); }
  .deals { grid-template-columns: 1fr; }
  .editorial { grid-template-columns: 1fr 1fr; }
  .newsletter { grid-template-columns: 1fr; padding: 32px; }
  .site-footer__inner { grid-template-columns: 1fr 1fr; }
  .search { display: none; }
  .site-header__inner { grid-template-columns: auto auto; }
  .primary-nav { display: none; }
}

@media (max-width: 640px) {
  .container { padding: 0 16px; }
  section { margin-top: 56px; }
  .hero { margin-top: 16px; border-radius: 18px; }
  .hero__grid { padding: 28px; gap: 24px; }
  .hero__meta { gap: 20px; }
  .product-grid { grid-template-columns: repeat(2, 1fr); gap: 14px; }
  .categories { grid-template-columns: repeat(2, 1fr); }
  .editorial { grid-template-columns: 1fr; }
  .site-footer__inner { grid-template-columns: 1fr; padding: 40px 16px 20px; }
  .promo-bar__links { display: none; }
  .deal-card { padding: 24px; min-height: 220px; }
}

@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    animation-duration: 0.01ms !important;
    transition-duration: 0.01ms !important;
  }
}

