const useCountdown = (target) => {
  const [now, setNow] = useState(Date.now());
  useEffect(() => {
    const id = setInterval(() => setNow(Date.now()), 1000);
    return () => clearInterval(id);
  }, []);
  const diff = Math.max(0, target - now);
  const d = Math.floor(diff / 86400000);
  const h = Math.floor((diff / 3600000) % 24);
  const m = Math.floor((diff / 60000) % 60);
  const s = Math.floor((diff / 1000) % 60);
  return { d, h, m, s };
};

const Countdown = () => {
  const target = useMemo(() => Date.now() + 3 * 86400000 + 7 * 3600000, []);
  const { d, h, m, s } = useCountdown(target);
  const fmt = (n) => String(n).padStart(2, "0");
  const live = `${d} days, ${h} hours, ${m} minutes`;
  return (
    <>
      <div className="countdown" aria-hidden="true">
        {[{n:d,l:"Days"},{n:h,l:"Hrs"},{n:m,l:"Min"},{n:s,l:"Sec"}].map(c => (
          <div className="countdown__cell" key={c.l}>
            <span className="countdown__num">{fmt(c.n)}</span>
            <span className="countdown__lbl">{c.l}</span>
          </div>
        ))}
      </div>
      <span className="sr-only" aria-live="polite">Sale ends in {live}</span>
    </>
  );
};

