const App = () => {
  const [cart, setCart] = useState([]);
  const [wishlist, setWishlist] = useState([]);
  const [toasts, setToasts] = useState([]);

  const pushToast = useCallback((message) => {
    const id = Date.now() + Math.random();
    setToasts(ts => [...ts, { id, message }]);
    setTimeout(() => setToasts(ts => ts.filter(t => t.id !== id)), 2800);
  }, []);

  const onAdd = useCallback((p) => {
    setCart(c => [...c, p.id]);
    pushToast(`Added "${p.title}" to your bag`);
  }, [pushToast]);

  const onWish = useCallback((id) => {
    setWishlist(w => w.includes(id) ? w.filter(x => x !== id) : [...w, id]);
  }, []);

  const onSearch = useCallback((q) => {
    if (q.trim()) pushToast(`Searching for "${q.trim()}"…`);
  }, [pushToast]);

  return (
    <>
      <a href="#main" className="skip-link">Skip to main content</a>
      <PromoBar />
      <Header cartCount={cart.length} wishlistCount={wishlist.length} onSearch={onSearch} />
      <main id="main" className="container" tabIndex="-1">
        <Hero />
        <Categories />
        <FeaturedProducts onAdd={onAdd} wishlist={wishlist} onWish={onWish} />
        <Deals />
        <Editorial />
        <Newsletter />
      </main>
      <Footer />
      <ToastRegion toasts={toasts} />
    </>
  );
};

ReactDOM.createRoot(document.getElementById("root")).render(<App />);
